-- GENERATED FILE. Edit src/lib/curriculum/**, then run:
--   node scripts/generate-curriculum-seed.mjs
--
-- Authoritative Ditch curriculum seed. Idempotent for sections, modules, paths,
-- quizzes, and search records. Legacy content is deactivated rather than deleted,
-- and generated path membership/questions are replaced only for owned IDs.
-- Existing completions, quiz attempts, and assignments are preserved.
-- Review in a non-production branch before applying. No remote database change
-- occurs by generating this file.

BEGIN;

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  slug = EXCLUDED.slug,
  "sortOrder" = EXCLUDED."sortOrder",
  "isActive" = true;

ON CONFLICT (id) DO UPDATE SET
  "sectionId" = EXCLUDED."sectionId",
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  slug = EXCLUDED.slug,
  content = EXCLUDED.content,
  "estimatedMinutes" = EXCLUDED."estimatedMinutes",
  "isRequired" = true,
  "isActive" = true,
  "sortOrder" = EXCLUDED."sortOrder",
  tags = EXCLUDED.tags;

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  "targetRole" = EXCLUDED."targetRole",
  "targetPositions" = EXCLUDED."targetPositions",
  "moduleIntervalDays" = EXCLUDED."moduleIntervalDays",
  "isActive" = true;

DELETE FROM "TrainingPathModule" WHERE "trainingPathId" IN ('path-hospitality-reset', 'path-leadership-operating-system', 'path-daily-masterminds', 'path-trainer-operating-system', 'path-server-onboarding', 'path-bartender-onboarding', 'path-support-onboarding');

-- Retire the replaced curriculum without breaking historical completions or attempts.
UPDATE "Section" SET "isActive" = false WHERE "isActive" = true AND id NOT IN ('sec-hospitality-reset', 'sec-leadership-operating-system', 'sec-daily-masterminds', 'sec-trainer-operating-system', 'sec-server-onboarding', 'sec-bartender-onboarding', 'sec-support-onboarding');
UPDATE "Module" SET "isActive" = false WHERE "isActive" = true AND id NOT IN ('cur-reset-promise-care', 'cur-reset-baseline-magic', 'cur-reset-whole-room', 'cur-reset-passion-selling', 'cur-reset-source-safety', 'cur-reset-last', 'cur-reset-accountability', 'cur-reset-live-certification', 'cur-leadership-week-0', 'cur-leadership-week-1', 'cur-leadership-week-2', 'cur-leadership-week-3', 'cur-leadership-week-4', 'cur-leadership-week-5', 'cur-leadership-week-6', 'cur-leadership-week-7', 'cur-leadership-week-8', 'cur-mastermind-unconditional-hospitality', 'cur-mastermind-passion-selling', 'cur-mastermind-last-recovery', 'cur-mastermind-accountability-without-ego', 'cur-trainer-identity-selection', 'cur-trainer-seven-step-method', 'cur-trainer-shift-autonomy', 'cur-trainer-coaching-learning', 'cur-trainer-four-labs', 'cur-trainer-certification-audit', 'cur-trainer-final-practical', 'cur-server-identity-readiness', 'cur-server-guest-journey', 'cur-server-food-menu', 'cur-server-beverage-menu', 'cur-server-passion-selling', 'cur-server-pos-pacing-safety', 'cur-server-recovery-payment', 'cur-server-final-practical', 'cur-bartender-identity-journey', 'cur-bartender-safe-responsible', 'cur-bartender-station-technique', 'cur-bartender-approved-signatures-1', 'cur-bartender-approved-signatures-2', 'cur-bartender-locked-rotating', 'cur-bartender-passion-pairing', 'cur-bartender-ticket-recovery', 'cur-bartender-open-close-control', 'cur-bartender-final-practical', 'cur-support-shared-core', 'cur-support-safety-map', 'cur-support-host-branch', 'cur-support-busser-branch', 'cur-support-runner-branch', 'cur-support-volume-system', 'cur-support-guest-questions-recovery', 'cur-support-final-practical');
UPDATE "TrainingPath" SET "isActive" = false WHERE "isActive" = true AND id NOT IN ('path-hospitality-reset', 'path-leadership-operating-system', 'path-daily-masterminds', 'path-trainer-operating-system', 'path-server-onboarding', 'path-bartender-onboarding', 'path-support-onboarding');
UPDATE "UserTrainingPath" utp
SET "isActive" = false
WHERE utp."isActive" = true
  AND EXISTS (
    SELECT 1
    FROM "TrainingPath" path
    WHERE path.id = utp."trainingPathId"
      AND path."isActive" = false
  );

-- Reconcile every active employee onto the all-team Hospitality Reset plus
-- every current path matching their explicit position.
-- Rollout deadlines start now for established employees so historic hire dates do not
-- make the replacement curriculum immediately overdue. Existing current-path links retain
-- their original deadlines; links to retired paths remain preserved as inactive history.
WITH applicable_paths AS (
  SELECT
    u.id AS user_id,
    p.id AS path_id,
    GREATEST(COALESCE(u."hireDate", CURRENT_TIMESTAMP::timestamp), CURRENT_TIMESTAMP::timestamp) AS rollout_start,
    GREATEST(p."moduleIntervalDays", 1) AS interval_days,
    COUNT(s.id)::integer AS module_count
  FROM "User" u
  JOIN "TrainingPath" p
    ON p.id = 'path-hospitality-reset'
    OR EXISTS (
      SELECT 1
      FROM "UserPosition" up
      WHERE up."userId" = u.id
        AND up."isActive" = true
        AND up.position = ANY (p."targetPositions")
    )
    OR (
      NOT EXISTS (
        SELECT 1
        FROM "UserPosition" up
        WHERE up."userId" = u.id
          AND up."isActive" = true
      )
      AND u.position = ANY (p."targetPositions")
    )
  LEFT JOIN "TrainingPathModule" tpm ON tpm."trainingPathId" = p.id
  LEFT JOIN "Module" m ON m.id = tpm."moduleId" AND m."isActive" = true
  LEFT JOIN "Section" s ON s.id = m."sectionId" AND s."isActive" = true
  WHERE u."isActive" = true
    AND p."isActive" = true
    AND p.id IN ('path-hospitality-reset', 'path-leadership-operating-system', 'path-daily-masterminds', 'path-trainer-operating-system', 'path-server-onboarding', 'path-bartender-onboarding', 'path-support-onboarding')
  GROUP BY u.id, u."hireDate", p.id, p."moduleIntervalDays"
)
SELECT
  user_id,
  path_id,
  rollout_start + make_interval(days => interval_days * module_count),
  'position',
  true
FROM applicable_paths
ON CONFLICT ("userId", "trainingPathId") DO UPDATE SET
  "dueDate" = CASE
    WHEN "UserTrainingPath"."isActive" = false THEN EXCLUDED."dueDate"
    ELSE "UserTrainingPath"."dueDate"
  END,
  "assignedReason" = CASE
    WHEN "UserTrainingPath"."isActive" = false THEN EXCLUDED."assignedReason"
    ELSE "UserTrainingPath"."assignedReason"
  END,
  "isActive" = true;

WITH applicable_modules AS (
  SELECT
    u.id AS user_id,
    p.id AS path_id,
    tpm."moduleId" AS module_id,
    tpm."isRequired" AS is_required,
    GREATEST(COALESCE(u."hireDate", CURRENT_TIMESTAMP::timestamp), CURRENT_TIMESTAMP::timestamp) AS rollout_start,
    GREATEST(p."moduleIntervalDays", 1) AS interval_days,
    (ROW_NUMBER() OVER (
      PARTITION BY u.id, p.id
      ORDER BY tpm."sortOrder", tpm."moduleId"
    ))::integer AS module_sequence
  FROM "User" u
  JOIN "TrainingPath" p
    ON p.id = 'path-hospitality-reset'
    OR EXISTS (
      SELECT 1
      FROM "UserPosition" up
      WHERE up."userId" = u.id
        AND up."isActive" = true
        AND up.position = ANY (p."targetPositions")
    )
    OR (
      NOT EXISTS (
        SELECT 1
        FROM "UserPosition" up
        WHERE up."userId" = u.id
          AND up."isActive" = true
      )
      AND u.position = ANY (p."targetPositions")
    )
  JOIN "TrainingPathModule" tpm ON tpm."trainingPathId" = p.id
  JOIN "Module" m ON m.id = tpm."moduleId" AND m."isActive" = true
  JOIN "Section" s ON s.id = m."sectionId" AND s."isActive" = true
  WHERE u."isActive" = true
    AND p."isActive" = true
    AND p.id IN ('path-hospitality-reset', 'path-leadership-operating-system', 'path-daily-masterminds', 'path-trainer-operating-system', 'path-server-onboarding', 'path-bartender-onboarding', 'path-support-onboarding')
)
SELECT
  user_id,
  module_id,
  is_required,
  rollout_start + make_interval(days => interval_days * module_sequence),
  false,
  ARRAY[path_id]::text[],
  true
FROM applicable_modules
ON CONFLICT ("userId", "moduleId") DO UPDATE SET
  "isRequired" = CASE
    WHEN "ModuleAssignment"."isActive" = false THEN EXCLUDED."isRequired"
    ELSE "ModuleAssignment"."isRequired" OR EXCLUDED."isRequired"
  END,
  "dueDate" = CASE
    WHEN "ModuleAssignment"."isActive" = false THEN EXCLUDED."dueDate"
    WHEN "ModuleAssignment"."dueDate" IS NULL THEN EXCLUDED."dueDate"
    WHEN EXCLUDED."dueDate" IS NULL THEN "ModuleAssignment"."dueDate"
    ELSE LEAST("ModuleAssignment"."dueDate", EXCLUDED."dueDate")
  END,
  "isActive" = true,
  "sourcePathIds" = CASE
    WHEN "ModuleAssignment"."isActive" = false THEN EXCLUDED."sourcePathIds"
    ELSE (
      SELECT ARRAY_AGG(DISTINCT source_id)
      FROM UNNEST("ModuleAssignment"."sourcePathIds" || EXCLUDED."sourcePathIds") AS source_id
    )
  END;

